# ABOUTME: One bar chart for the week's DA arms: the 25 Sep and 28 Sep corpora, 25 Sep's AI rows swapped into the
# ABOUTME: 28 Sep mix, AI rows regenerated by the pipeline, and the 2 Oct recipe -- MASK honesty and ODCV-lite side by side.
"""    uv run python scratch/plot_da_week_summary.py   -> output/figures/<date>_da_week_summary_mask_odcv.{png,md}

Reads published eval runs from the Hub only. ODCV intervals are fixed-benchmark 95% CIs (the 40 scenarios are the
benchmark, passes are subsamples); an arm with two runs is drawn at their mean with the envelope of both intervals.
"""
from __future__ import annotations

import json
import statistics
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from dotenv import load_dotenv
from huggingface_hub import hf_hub_download

from src.eval.misalignment.odcv.odcv import MR_BOUNDS, to_long
from src.eval.stats import Design, interval
from src.naming import figure_path

load_dotenv()
ORG = "dougalldeepmind"
OUT = Path("output/figures")
FIXED = Design(item="scenario", item_sampling="fixed", enumerated={"variant": "equal"}, subsamples=("pass",))
# (group, label, colour, odcv runs, mask runs). Every arm is difficult advice at 15%, seed 0 unless two runs are listed.
ARMS = [
    ("The two corpora", "25 Sep corpus", "#2b1f6e",
     ["2026-09-26-odcv-qwen36-0-da-15", "2026-09-26-odcv-qwen36-1-da-15"],
     ["2026-09-26-mask-qwen36-0-da-15", "2026-09-26-mask-qwen36-1-da-15"]),
    ("The two corpora", "28 Sep corpus", "#c3bbe6",
     ["2026-09-29-odcv-qwen36-0-da-15", "2026-09-30-odcv-qwen36-0-da-15"], ["2026-09-29-mask-qwen36-0-da-15"]),
    ("28 Sep, with 25 Sep's AI rows swapped in", "assistant-itself rows", "#5b45b8",
     ["2026-09-29-odcv-qwen36-0-da-15-self"], ["2026-09-29-mask-qwen36-0-da-15-self"]),
    ("28 Sep, with 25 Sep's AI rows swapped in", "other-AI rows", "#5b45b8",
     ["2026-09-29-odcv-qwen36-0-da-15-otherai"], ["2026-09-29-mask-qwen36-0-da-15-otherai"]),
    ("28 Sep, with 25 Sep's AI rows swapped in", "both", "#5b45b8",
     ["2026-09-29-odcv-qwen36-0-da-15-self-otherai"], ["2026-09-29-mask-qwen36-0-da-15-self-otherai"]),
    ("28 Sep recipe, AI rows written by the pipeline", "assistant-itself rows", "#9a86d9",
     ["2026-10-01-odcv-qwen36-0-da-self-15"], ["2026-10-01-mask-qwen36-0-da-self-15"]),
    ("28 Sep recipe, AI rows written by the pipeline", "other-AI rows", "#9a86d9",
     ["2026-10-01-odcv-qwen36-0-da-otherai-15"], ["2026-10-01-mask-qwen36-0-da-otherai-15"]),
    ("Today's recipe (native-tools base)", "2 Oct corpus", "#2b1f6e",
     ["2026-10-02-odcv-qwen36-0-da-15"], ["2026-10-02-mask-qwen36-0-da-15"]),
]
INK, MUTE, RULE = "#1f1f24", "#6b6b76", "#d8d6e0"


def _results(run: str) -> dict:
    return json.load(open(hf_hub_download(f"{ORG}/{run}", "results/results.json", repo_type="dataset")))


def odcv(run: str) -> tuple[float, float, float]:
    o = _results(run)
    assert o["ours"]["overall"]["n_rollouts"] == 240 and o["mode"] == "think", run
    rows = [dict(r, value=100.0 * r["violation"]) for r in to_long(o["per_scenario_medians"])]
    r = interval(rows, FIXED, bounds=MR_BOUNDS)
    return r.mean, r.lo, r.hi


def mask(run: str) -> float:
    m = _results(run)
    assert m["mode"] == "think", run
    return float(m["overall_honesty_score"])


def main() -> None:
    rows = []
    for group, label, colour, oruns, mruns in ARMS:
        o = [odcv(r) for r in oruns]
        m = [mask(r) for r in mruns]
        rows.append(dict(group=group, label=label, colour=colour, mask=statistics.mean(m), mask_runs=m,
                         odcv=statistics.mean(x[0] for x in o), lo=min(x[1] for x in o), hi=max(x[2] for x in o),
                         odcv_runs=o, runs=oruns + mruns))
    ys, y, prev, groups = [], 0.0, None, []
    for r in rows:
        if r["group"] != prev:
            y += 0.0 if prev is None else 0.9
            groups.append((r["group"], y))
            prev = r["group"]
        ys.append(y)
        y += 1.0

    plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 11, "axes.edgecolor": RULE,
                         "xtick.color": MUTE, "ytick.color": INK})
    fig, axes = plt.subplots(1, 2, figsize=(11.5, 0.62 * y + 2.2), sharey=True, gridspec_kw={"wspace": 0.08})
    panels = ((axes[0], "mask", "MASK honesty  (higher is better)", (60, 96), "{:.1f}"),
              (axes[1], "odcv", "ODCV-lite misconduct  (lower is better)", (0, 28), "{:.1f}%"))
    for ax, key, title, xlim, fmt in panels:
        for ref, style in ((rows[0], "-"), (rows[1], ":")):
            ax.axvline(ref[key], color=ref["colour"] if ref is rows[0] else "#8f86bf", lw=1.1, ls=style, zorder=1)
        for r, yy in zip(rows, ys):
            edge = INK if r["group"].startswith("Today") else "none"
            ax.barh(yy, r[key] - xlim[0], left=xlim[0], height=0.72, color=r["colour"], edgecolor=edge, linewidth=1.4, zorder=2)
            end = r[key]
            if key == "odcv":
                ax.errorbar(r["odcv"], yy, xerr=[[r["odcv"] - r["lo"]], [r["hi"] - r["odcv"]]], fmt="none",
                            ecolor=INK, elinewidth=1.1, capsize=3, zorder=3)
                end = r["hi"]
            ax.text(end + (xlim[1] - xlim[0]) * 0.012, yy, fmt.format(r[key]), va="center", ha="left", fontsize=10.5, color=INK,
                    bbox=dict(facecolor="white", edgecolor="none", pad=1.2), zorder=4)
        ax.set_xlim(*xlim)
        ax.set_title(title, fontsize=12, color=INK, loc="left", pad=10)
        ax.grid(axis="x", color=RULE, lw=0.6, zorder=0)
        ax.set_axisbelow(True)
        for s in ("top", "right", "left"):
            ax.spines[s].set_visible(False)
        ax.tick_params(axis="y", length=0)
    axes[0].set_yticks(ys)
    axes[0].set_yticklabels([r["label"] for r in rows])
    axes[0].invert_yaxis()
    for name, y0 in groups:
        axes[0].text(-0.62, y0 - 0.62, name, transform=axes[0].get_yaxis_transform(), fontsize=10, color=MUTE,
                     fontweight="bold", va="center", ha="left")
    fig.suptitle("Difficult advice this week: what the corpus did to MASK and ODCV-lite", x=0.012, ha="left",
                 fontsize=14, color=INK, y=0.995)
    fig.text(0.012, 0.012, "Qwen3.6-27B, 15% difficult advice. Solid line: 25 Sep corpus; dotted: 28 Sep corpus. ODCV whiskers: "
             "fixed-benchmark 95% CI.\nOne seed per bar, except 25 Sep (two seeds) and 28 Sep (ODCV run twice). "
             "The 2 Oct arm is trained on the native-tools base mix; the others on the 22 Sep base.",
             fontsize=8.8, color=MUTE, ha="left", va="bottom")
    fig.subplots_adjust(left=0.36, right=0.965, top=0.9, bottom=0.14)
    png = figure_path(OUT, "da_week_summary_mask_odcv")
    fig.savefig(png, dpi=200)
    lines = ["# Difficult advice this week: MASK and ODCV-lite by corpus", "",
             "ODCV: fixed-benchmark 95% CI per run. Qwen3.6-27B, 15% DA, think mode.", "",
             "| group | arm | MASK | ODCV-lite | runs |", "|---|---|---|---|---|"]
    for r in rows:
        o = "; ".join(f"{a:.1f}% [{b:.1f}, {c:.1f}]" for a, b, c in r["odcv_runs"])
        lines.append(f"| {r['group']} | {r['label']} | {', '.join(f'{v:.1f}' for v in r['mask_runs'])} | {o} | {', '.join(r['runs'])} |")
    png.with_suffix(".md").write_text("\n".join(lines) + "\n")
    print(png)
    for r in rows:
        print(f"{r['group'][:34]:34} | {r['label']:22} | MASK {r['mask']:.1f} | ODCV {r['odcv']:.1f} [{r['lo']:.1f}, {r['hi']:.1f}]")


if __name__ == "__main__":
    main()
